 auto attachment=result->paint_sampling_attachment();auto base=source->snapshot(),edited=result->snapshot();ink(*base);ink(*edited);check(data_equal(*base,*edited),"Actual 3D stamps after UV changes write exact same independent corner-domain texels for all channels");check(images_equal(*base->composite(material),*edited->composite(material)),"All-channel paint after retained-domain change preserves exact composite images");check(edited->valid_paint_sampling_attachment()&&edited->paint_sampling_attachment()==attachment,"Mutable paint does not invalidate the geometry-only seal");
 edited->layer_properties("Renamed retained layer",true,.6f);check(edited->valid_paint_sampling_attachment()&&edited->paint_sampling_attachment()==attachment,"Legal layer/style changes do not invalidate sealed geometry");
