 auto snapshot=result->snapshot();check(snapshot->paint_sampling_attachment()==attachment&&snapshot->valid_paint_sampling_attachment(),"Immutable snapshot retains its exact sealed attachment without rebuilding geometry");allocation::remaining=0;bool exact=true;for(size_t n=0;n<10000;++n)exact&=result->valid_paint_sampling_attachment();allocation::remaining=-1;check(exact,"Ten thousand cheap owner checks allocate nothing and never replay mesh/plane values");
 check(refuses([&]{result->encode();}),"Context-free legacy serialization cannot silently discard the unadmitted Scene24 domain");check(refuses([&]{result->reparameterize(target);}),"Legacy UV path cannot silently discard the independent writable domain");
 size_t polls=0;PaintSamplingLimits measured;measured.cancelled=[&]{++polls;return false;};retain_paint_grid(*source,target,domain,measured);check(polls>5,"Actual domain/raster/cache/seal publication cancellation phases are measured");for(auto end:{size_t(1),polls/2,polls}){size_t current=0;auto limits=measured;limits.cancelled=[&]{return ++current>=end;};check(refuses([&]{retain_paint_grid(*source,target,domain,limits);})&&current==end&&data_equal(*source,*result),"Early/middle/final grid cancellation preserves original pixels and immutable owners");}
 allocation::calls=0;allocation::measure=true;auto sampled=retain_paint_grid(*source,target,domain);allocation::measure=false;const auto calls=allocation::calls;check(calls>10,"Actual grid, snapshot, cache and seal allocations are measured");
 for(size_t prefix=0;prefix<calls;++prefix){bool failed=false;allocation::remaining=long(prefix);allocation::hit=false;try{retain_paint_grid(*source,target,domain);}catch(const std::bad_alloc&){failed=true;}catch(...){allocation::remaining=-1;throw;}allocation::remaining=-1;check(failed&&allocation::hit&&data_equal(*source,*result)&&same(source->mesh(),mesh_before),"Every persistent grid allocation boundary preserves exact source, planes, layers and geometry");auto retry=retain_paint_grid(*source,target,domain);check(retry->valid_paint_sampling_attachment()&&data_equal(*source,*retry),"Every failed grid capture permits exact successful retry");}
